void Solver::restart() {
    // Aggressively reset LBD statistics
    fast_lbd_sum = 0;
    lbd_queue_size = 0;
    lbd_queue_pos = 0;

    // Return to root level
    backtrack(0);

    // Rephase variables with a mixed strategy
    for (int i = 1; i <= vars; ++i) {
        int r = rand() % 100;
        if (r < 30) {
            // Keep the best phase observed so far
            saved[i] = local_best[i];
        } else if (r < 55) {
            // Flip the best phase
            saved[i] = -local_best[i];
        } else {
            // Assign a completely random phase
            saved[i] = (rand() & 1) ? 1 : -1;
        }
    }

    // Slightly increase variable activity increment to diversify search after restart
    var_inc *= 1.2;
}

