void Solver::restart() {
    // Aggressively reset LBD statistics
    fast_lbd_sum = 0;
    lbd_queue_size = 0;
    lbd_queue_pos = 0;
    slow_lbd_sum = 0;

    // Backtrack to the root level
    backtrack(0);

    // Re‑phase variables: mix best, opposite, and random choices
    int r = rand() % 100;
    if (r < 50) {
        for (int i = 1; i <= vars; ++i) saved[i] = local_best[i];
    } else if (r < 75) {
        for (int i = 1; i <= vars; ++i) saved[i] = -local_best[i];
    } else {
        for (int i = 1; i <= vars; ++i) saved[i] = (rand() & 1) ? 1 : -1;
    }

    // Decay variable activity to diversify future decisions
    var_inc = 1.0;
    for (int i = 1; i <= vars; ++i) {
        activity[i] *= 0.5;
        if (!vsids.inHeap(i)) vsids.insert(i);
    }
}
